-- koloni-203: nem kademeleri — <55 kritik, <60 erken uyarı (normal alt), 60–75 normal, >75 nötr, >80 kireç riski; tümü 24 sa. 55/60/75 uzman tahmini (kullanıcı seçimi); Doull 1976 (%50) yalnız ilgili.
update public.ogul_skor_ayar set data = jsonb_set(jsonb_set(coalesce(data,'{}'::jsonb), '{sensor,nemNormalAlt}', '60'::jsonb, true), '{sensor,nemKritikAlt}', '55'::jsonb, true), updated_at = now() where id = 1;
insert into public.ayar_surumleri (data, fark, not_, yayinlayan_eposta)
select o.data, jsonb_build_object('sensor.nemNormalAlt', jsonb_build_object('once', 50, 'sonra', 60), 'sensor.nemKritikAlt', jsonb_build_object('sonra', 55)), 'koloni-203: nem kademeleri 55 / 60 / 75 / 80', 'migration' from public.ogul_skor_ayar o where o.id = 1;
update public.yapilacaklar set baslik = 'Nem kademeleri: <55 kritik, <60 erken, 60–75 normal, >75 nötr (24 sa, uzman tahmini)', aciklama = 'koloni-203, kullanıcı seçimi. 55/60/75 ve 24 sa kaynaksız. İlgili: Doull 1976 doi:10.1051/apido:19760104 (%50 altında yumurta açılmadı). Metinler: kritik «Nem çok düşük, yavru (yumurta) açılmama riski var», erken «Nem düşüyor, yavrularda kuruma riski var» (kaynak aranıyor), üst nötr. >80 kireç ayrı madde.', guncelleme = now() where id = 47;
